import{_ as a,C as s,o as d,c as i,a2 as t,E as r,w as c,j as n}from"./chunks/framework.-o-gwMjE.js";const f=JSON.parse('{"title":"Object lists","description":"","frontmatter":{},"headers":[],"relativePath":"language/object-lists.md","filePath":"language/object-lists.md"}'),l={name:"language/object-lists.md"};function p(h,e,m,g,b,_){const o=s("DocsBlock");return d(),i("div",null,[e[1]||(e[1]=t('<h1 id="object-lists" tabindex="-1">Object lists <a class="header-anchor" href="#object-lists" aria-label="Permalink to &quot;Object lists&quot;">​</a></h1><p>Reach ships a folder of plain-text <strong>object lists</strong> beside the Megalo scripts. In a default Halo Reach Editing Kit (HREK) install they live at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/multiplayer/megalo/object_lists/</span></span></code></pre></div><p>(for example <code>…/HREK/data/multiplayer/megalo/object_lists/</code> under Steam).</p><p>Bungie&#39;s Megalo editor (<strong>MegaloEdit</strong>) loads these files for autocomplete, syntax help, and the <strong>Help</strong> menu reference lists. The game engine uses the same tables to turn symbolic names in scripts into numeric indices when a gametype or custom variant is compiled.</p><p>These lists correspond to data in the <code>loadout_globals_definition</code> (<code>lgtd</code>), <code>megalo_string_id_table</code> (<code>msit</code>), and <code>multiplayer_object_type_list</code> (<code>motl</code>) tags.</p>',6)),r(o,{type:"info",title:"Custom maps"},{default:c(()=>[...e[0]||(e[0]=[n("p",null,"Everything in the object lists corresponds to data in your tags. That lets you author Megalo scripts for custom maps with custom objects, weapons, vehicles, and other map-specific entries — not just stock Reach content.",-1)])]),_:1}),e[2]||(e[2]=t('<h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><p>Each file is a simple lookup table:</p><ul><li><strong>One entry per line</strong> — a snake_case identifier with no punctuation.</li><li><strong>Line order is the index</strong> — the first line is index <code>0</code> (or id <code>1</code> where noted below). Blank lines in some lists (notably <code>incidents.txt</code>) still consume an index slot in the engine.</li><li><strong>Names are stable vocabulary</strong> — you type them literally in Megalo source (<code>action create_object warthog …</code>, <code>submit_incident kill</code>, and so on).</li></ul><p>These lists are <strong>not</strong> Megalo script elements. They are engine data that scripts reference by name.</p><h2 id="what-each-file-is-for" tabindex="-1">What each file is for <a class="header-anchor" href="#what-each-file-is-for" aria-label="Permalink to &quot;What each file is for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Entries</th><th>Used for</th><th>Tag</th></tr></thead><tbody><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/objects.txt" target="_blank" rel="noreferrer"><code>objects.txt</code></a></td><td>~220</td><td><strong>Master object type table.</strong> Weapons, vehicles, equipment, scenery, spawn points, Forge objects, and special markers. Referenced by <code>create_object</code>, <code>object_matches_filter</code>, respawn/vehicle actions, and <code>map_object</code> <code>type</code> fields.</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/weapons.txt" target="_blank" rel="noreferrer"><code>weapons.txt</code></a></td><td>24</td><td><strong>Player trait primary/secondary weapons.</strong> Subset of <code>objects.txt</code> in a fixed order. Used in <code>player_traits</code> blocks (<code>primary_weapon</code>, <code>secondary_weapon</code>). Indices are resolved against which object types the gametype actually uses.</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/equipment.txt" target="_blank" rel="noreferrer"><code>equipment.txt</code></a></td><td>10</td><td><strong>Player trait equipment slot.</strong> Armor abilities and equipment (<code>sprint_equipment</code>, <code>jet_pack_equipment</code>, …). Same absolute-index rules as weapons.</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/vehicles.txt" target="_blank" rel="noreferrer"><code>vehicles.txt</code></a></td><td>34</td><td><strong>Vehicle names</strong> for trait and filter operands where the editor offers a vehicle picker (subset of entries from <code>objects.txt</code>).</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/grenades.txt" target="_blank" rel="noreferrer"><code>grenades.txt</code></a></td><td>4</td><td><strong>Grenade types</strong> in <code>player_traits</code> <code>initial_grenades</code> (<code>frag_grenade</code>, <code>plasma_grenade</code>, <code>spike_grenade</code>, <code>firebomb_grenade</code>).</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/incidents.txt" target="_blank" rel="noreferrer"><code>incidents.txt</code></a></td><td>~470</td><td><strong>Game incidents</strong> for <code>submit_incident</code> and <code>submit_incident_with_custom_value</code>. Covers kills, medals, mode events (CTF, KOTH, Infection, …), survival, achievements, and announcer triggers. Incident ids are <strong>1-based</strong> (first line = incident <code>1</code>).</td><td><code>globals\\incident.properties.incident_global_properties_definition</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/loadout_palettes.txt" target="_blank" rel="noreferrer"><code>loadout_palettes.txt</code></a></td><td>15</td><td><strong>Loadout palette presets</strong> for <code>set_loadout_palette</code> and <code>override loadout_palette</code> (<code>slayer_loadouts</code>, <code>objective_loadouts</code>, firefight palettes, …).</td><td><code>multiplayer\\invasion.loadout_globals_definition</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/loadouts.txt" target="_blank" rel="noreferrer"><code>loadouts.txt</code></a></td><td>~80</td><td><strong>Loadout display names</strong> (<code>loadout_name_carter</code>, <code>loadout_name_ninja</code>, …). Used by the editor and UI when presenting loadout choices, not as action opcodes.</td><td><code>multiplayer\\invasion.loadout_globals_definition</code></td></tr><tr><td><span id="weapon_sets"><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/weapon_sets.txt" target="_blank" rel="noreferrer"><code>weapon_sets.txt</code></a></span></td><td>16</td><td><strong>Weapon restriction presets</strong> for <code>override weapon_set</code> in <a href="/MegaCrow/alpha/docs/language/elements/game-options"><code>game_options</code></a>. See <a href="/MegaCrow/alpha/docs/language/enums/game-options/weapon-set">Weapon Set</a> for sentinel tokens (<code>none</code>, <code>default</code>, <code>random</code>) and the full preset list.</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><span id="vehicle_sets"><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/vehicle_sets.txt" target="_blank" rel="noreferrer"><code>vehicle_sets.txt</code></a></span></td><td>14</td><td><strong>Vehicle restriction presets</strong> for <code>override vehicle_set</code> (<code>mongoose_only</code>, <code>no_aircraft</code>, <code>all_vehicles</code>, …). See <a href="/MegaCrow/alpha/docs/language/enums/game-options/vehicle-set">Vehicle Set</a> for sentinel tokens and indices.</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/hud_widget_icons.txt" target="_blank" rel="noreferrer"><code>hud_widget_icons.txt</code></a></td><td>33</td><td><strong>HUD widget icons</strong> for <code>hud_widget_set_icon</code> (<code>slayer</code>, <code>ctf</code>, <code>koth</code>, <code>generic_icon_2</code>, …). Some names in this list (spartan onward) don&#39;t match their respective icon in-game, seemingly because more icons were inserted later without the list being updated.</td><td><code>ui\\chud\\bitmaps\\variant_items\\gametypes.bitmap</code> (This tag has the icons that display in-game, but the tool command <code>multiplayer-generate-all-string-lists</code> does not update the list and it must be manually updated. This tag also coresponds to the icons shown via <code>player_set_objective_allegiance_icon</code>, but that action does not use this list.)</td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/strings.txt" target="_blank" rel="noreferrer"><code>strings.txt</code></a></td><td>~58</td><td><strong>String tokens</strong> for <code>device_animate_position</code> and related device actions (map-specific animation names like <code>mp_boneyard_a_fly_in</code>), object variants used with <code>create_object</code> (such as <code>default</code> and <code>carter</code>), and function names for <code>hs_function_call</code> (none available by default).</td><td><code>multiplayer\\megalo\\global.megalo_string_id_table</code></td></tr></tbody></table><h2 id="relationship-to-objects-txt" tabindex="-1">Relationship to <code>objects.txt</code> <a class="header-anchor" href="#relationship-to-objects-txt" aria-label="Permalink to &quot;Relationship to `objects.txt`&quot;">​</a></h2><p>Most specialized lists are <strong>subsets or views</strong> of the master <code>objects.txt</code> table:</p><ul><li><code>weapons.txt</code> and <code>equipment.txt</code> list names that also appear in <code>objects.txt</code>, but player traits encode them using a compressed <strong>absolute index</strong> that depends on which object types the gametype marks as used.</li><li><code>vehicles.txt</code> is a convenience list for vehicle pickers; vehicle types still resolve through <code>objects.txt</code> indices in compiled data.</li></ul><p>When in doubt, check whether a name exists in <code>objects.txt</code> — that is the authoritative object-type namespace for spawn and filter actions.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaCrow/alpha/docs/language/">Megalo language overview</a> — <code>map_object</code>, <code>player_traits</code>, and actions that consume these names</li><li><a href="/MegaCrow/alpha/docs/versions/">Megalo Versions</a> — action opcodes per Reach build</li></ul>',12))])}const y=a(l,[["render",p]]);export{f as __pageData,y as default};
